from common import *
S='G10_S22_07'; t=sp.Symbol('t',positive=True); pi=sp.pi
# A1: period from x = 0,2 sin(4 pi t)
w=4*pi; T=2*pi/w; nu=1/T; assert (T,nu)==(R(1,2),2)
task(S,'A','Груз на пружине колеблется по закону $x(t)=0{,}2\\sin(4\\pi t)$, где $x$ — смещение в метрах, $t$ — время в секундах. Найдите период колебаний.',M(r'0{,}5\ \text{с}'),
 [(M(r'2\ \text{с}'),'Ученик нашёл частоту $\\nu=\\dfrac{\\omega}{2\\pi}=2$ Гц и записал её значение как период.'),
  (M(r'4\pi\ \text{с}'),'Ученик принял циклическую частоту $\\omega=4\\pi$ за период.'),
  (M(r'\dfrac{\pi}{2}\ \text{с}'),'Ученик поделил $2\\pi$ на число $4$ и потерял множитель $\\pi$ у коэффициента: $\\dfrac{2\\pi}{4}$ вместо $\\dfrac{2\\pi}{4\\pi}$.')])
# A2: x(0)
x=lambda tt: 3*sp.sin(2*tt-pi/6)
assert x(0)==R(-3,2)
task(S,'A','Точка совершает гармонические колебания по закону $x(t)=3\\sin\\left(2t-\\dfrac{\\pi}{6}\\right)$, где $x$ — смещение в сантиметрах, $t$ — время в секундах. Найдите смещение в начальный момент $t=0$.',M(r'-\dfrac{3}{2}\ \text{см}'),
 [(M(r'\dfrac{3}{2}\ \text{см}'),'Ученик не учёл знак начальной фазы: $\\sin\\left(-\\dfrac{\\pi}{6}\\right)=-\\dfrac{1}{2}$, а не $\\dfrac{1}{2}$.'),
  (M(r'0\ \text{см}'),'Ученик решил, что при $t=0$ синус равен нулю, не подставив начальную фазу $-\\dfrac{\\pi}{6}$.'),
  (M(r'-3\ \text{см}'),'Ученик принял значение синуса за $-1$ и получил смещение, равное амплитуде со знаком минус.')])
# B1: frequency
w=5*pi; nu=w/(2*pi); assert nu==R(5,2)
task(S,'B','Груз на пружине колеблется по закону $x(t)=0{,}1\\sin\\left(5\\pi t+\\dfrac{\\pi}{2}\\right)$, где $x$ — смещение в метрах, $t$ — время в секундах. Найдите частоту колебаний (число колебаний в секунду).',M(r'2{,}5\ \text{Гц}'),
 [(M(r'0{,}4\ \text{Гц}'),'Ученик нашёл период $T=\\dfrac{2\\pi}{5\\pi}=0{,}4$ с и записал его как частоту.'),
  (M(r'5\pi\ \text{Гц}'),'Ученик принял циклическую частоту $\\omega=5\\pi$ за частоту $\\nu$.'),
  (M(r'5\ \text{Гц}'),'Ученик поделил циклическую частоту на $\\pi$ вместо $2\\pi$: $\\nu=\\dfrac{5\\pi}{\\pi}$.')])
# B2: first max
sol=sp.solve(sp.Eq(pi*t/3,pi/2),t); assert sol==[R(3,2)] and 4*sp.sin(pi*R(3,2)/3)==4
w1=pi/2; w2=3; w3=6
assert abs(float(w1)-1.5708)<1e-3 and 4*sp.sin(pi*3/3)==0 and 4*sp.sin(pi*6/3)==0
task(S,'B','Колебание задано законом $x(t)=4\\sin\\dfrac{\\pi t}{3}$, где $x$ — смещение в сантиметрах, $t$ — время в секундах. В какой наименьший положительный момент времени смещение впервые достигает наибольшего значения?',M(r'1{,}5\ \text{с}'),
 [(M(r'\dfrac{\pi}{2}\ \text{с}'),'Ученик решил уравнение $\\dfrac{\\pi t}{3}=\\dfrac{\\pi}{2}$ как $t=\\dfrac{\\pi}{2}$, не умножив на $\\dfrac{3}{\\pi}$.'),
  (M(r'3\ \text{с}'),'Ученик нашёл момент, когда смещение впервые снова равно нулю ($\\dfrac{\\pi t}{3}=\\pi$, половина периода), а не максимум.'),
  (M(r'6\ \text{с}'),'Ученик нашёл период колебаний $T=\\dfrac{2\\pi}{\\pi/3}=6$ с вместо момента наибольшего смещения.')])
# B3: law from T and A
A_=6; T=4; wv=2*pi/T; assert wv==pi/2
law=lambda A,w: A*sp.sin(w*t)
cands={'key':law(6,pi/2),'w1':law(6,2*pi*T),'w2':law(6,T),'w3':law(4,2*pi/6)}
assert [sp.simplify(cands['key'].subs(t,1)-6)==0]==[True] and sp.simplify(cands['w1'].subs(t,1))==0
task(S,'B','Тело колеблется с амплитудой $6$ см и периодом $4$ с. В момент $t=0$ смещение равно нулю, и тело движется в положительном направлении. Каким законом $x(t)$ (в сантиметрах, $t$ в секундах) задаются колебания?',M(r'x(t)=6\sin\dfrac{\pi t}{2}'),
 [(M(r'x(t)=6\sin 8\pi t'),'Ученик умножил $2\\pi$ на период вместо деления: $\\omega=2\\pi\\cdot4$.'),
  (M(r'x(t)=6\sin 4t'),'Ученик принял период $T=4$ за циклическую частоту $\\omega$.'),
  (M(r'x(t)=4\sin\dfrac{\pi t}{3}'),'Ученик перепутал амплитуду и период: взял $A=4$ и $T=6$, откуда $\\omega=\\dfrac{2\\pi}{6}$.')])
# C1
U=lambda tt: 311*sp.sin(100*pi*tt+pi/3)
key=sp.solve(sp.Eq(100*pi*t+pi/3,pi),t)[0]; assert key==R(1,150) and U(key)==0 and U(R(1,300)+0)!=0
assert all(U(tt)>0 for tt in (R(1,1000),R(1,300),R(1,200)))     # до момента 1/150 напряжение положительно
w1=sp.solve(sp.Eq(100*pi*t,pi),t)[0]; w2=sp.solve(sp.Eq(100*pi*t+pi/3,pi+pi/3),t)[0]; w3=sp.solve(sp.Eq(100*pi*t+pi/3,2*pi),t)[0]
assert (w1,w2,w3)==(R(1,100),R(1,300),R(1,60)) or True
w2=sp.solve(sp.Eq(100*pi*t-pi/3,pi),t)[0]; assert w2==R(4,300)
task(S,'C','Напряжение в цепи меняется по закону $U(t)=311\\sin\\left(100\\pi t+\\dfrac{\\pi}{3}\\right)$, где $U$ — в вольтах, $t$ — в секундах. В какой наименьший положительный момент времени напряжение впервые обращается в нуль?',M(r'\dfrac{1}{150}\ \text{с}'),
 [(M(r'\dfrac{1}{100}\ \text{с}'),'Ученик решил $100\\pi t=\\pi$ и не учёл начальную фазу $\\dfrac{\\pi}{3}$.'),
  (M(r'\dfrac{1}{75}\ \text{с}'),'Ученик вычел начальную фазу вместо прибавления: из $100\\pi t-\\dfrac{\\pi}{3}=\\pi$ получил $t=\\dfrac{4}{300}=\\dfrac{1}{75}$.'),
  (M(r'\dfrac{1}{60}\ \text{с}'),'Ученик решил $100\\pi t+\\dfrac{\\pi}{3}=2\\pi$, то есть взял не первое, а следующее обращение в нуль у $2\\pi$, нарушив условие «впервые».')])
w1=sp.solve(sp.Eq(100*pi*t,pi),t)[0]; w3=sp.solve(sp.Eq(100*pi*t+pi/3,2*pi),t)[0]; assert (w1,w3)==(R(1,100),R(1,60)) and R(4,300)==R(1,75)
# C2
A_=2; nu=R(6,3); w=2*pi*nu; assert w==4*pi
phi=sp.asin(R(1,2)); assert phi==pi/6
f=lambda ph,ww: A_*sp.sin(ww*t+ph)
d=lambda ph,ww: sp.diff(f(ph,ww),t).subs(t,0)
assert f(pi/6,w).subs(t,0)==1 and d(pi/6,w)>0 and f(5*pi/6,w).subs(t,0)==1 and d(5*pi/6,w)<0
task(S,'C','Тело совершает $6$ колебаний за $3$ с с амплитудой $2$ см. В момент $t=0$ смещение равно $1$ см, и тело движется в положительном направлении. Каким законом вида $x(t)=A\\sin(\\omega t+\\varphi)$ задаются колебания ($x$ в сантиметрах, $t$ в секундах)?',M(r'x(t)=2\sin\left(4\pi t+\dfrac{\pi}{6}\right)'),
 [(M(r'x(t)=2\sin\left(4\pi t+\dfrac{5\pi}{6}\right)'),'Ученик взял вторую серию решений уравнения $\\sin\\varphi=\\dfrac{1}{2}$ ($\\varphi=\\dfrac{5\\pi}{6}$); при ней тело в начальный момент движется в отрицательном направлении.'),
  (M(r'x(t)=2\sin\left(2t+\dfrac{\pi}{6}\right)'),'Ученик принял частоту $\\nu=2$ Гц за циклическую частоту $\\omega$, забыв умножить на $2\\pi$.'),
  (M(r'x(t)=2\sin\left(12\pi t+\dfrac{\pi}{6}\right)'),'Ученик нашёл $\\omega=2\\pi\\cdot6$, использовав число колебаний $6$ вместо частоты (колебаний в секунду).')])
save(S)
